begin;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='a@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select ok(public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','agenda.test','agenda'),'A autoriza Agenda');
select ok(public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','packages.test','packages'),'A autoriza Pacotes');
select ok(not public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','packages.test','core'),'Não permite passar core para burlar módulo');
select is((select count(*)::int from public.module_test_records),2,'RLS A vê seus dois registros autorizados');
select lives_ok($$select public.module_probe('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','packages')$$,'RPC A Pacotes autorizada');
select throws_ok($$select public.provision_tenant(gen_random_uuid(),'ataque','Ataque','Centro','Marca','Fulano','x@example.com','complete')$$,'42501',null,'Admin clínico não provisiona');
select throws_ok($$select public.set_tenant_plan('10000000-0000-0000-0000-000000000001','complete','Escalada')$$,'42501',null,'Admin clínico não muda plano');
select throws_ok($$select public.set_module_override('10000000-0000-0000-0000-000000000001','packages',true,now()+interval '1 day','Escalada')$$,'42501',null,'Admin clínico não concede override');
select throws_ok($$select public.grant_support('10000000-0000-0000-0000-000000000001',auth.uid(),'diagnostics',60,'Escalada')$$,'42501',null,'Admin clínico não concede suporte');
select throws_ok($$update public.tenant_subscriptions set unit_limit_override=999$$,'42501',null,'Quota não editável diretamente');
select throws_ok($$update public.module_catalog set dependencies='{}'$$,'42501',null,'Catálogo não editável pelo cliente');
select throws_ok($$select public.claim_invitation_delivery(gen_random_uuid())$$,'42501',null,'Chave pública não aciona worker privilegiado');
create temp table preview as select public.preview_module('10000000-0000-0000-0000-000000000001','packages',false) id;
select ok(public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','packages.test','packages'),'Prévia não altera acesso');
select lives_ok($$select public.publish_module((select id from preview))$$,'Publicação revisada permitida');
select ok(not public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','packages.test','packages'),'Publicação desabilita módulo');
select is((select count(*)::int from public.module_test_records),1,'RLS remove módulo desabilitado');
select lives_ok($$select public.publish_module(public.preview_module('10000000-0000-0000-0000-000000000001','packages',true))$$,'Reativação dentro da alçada');
select throws_ok($$select public.publish_module(public.preview_module('10000000-0000-0000-0000-000000000001','agenda',false))$$,'42501',null,'Dependência ativa impede desligar Agenda');
reset role;
update public.tenant_entitlements set valid_until=now()+interval '1 second',valid_from=now()-interval '1 day' where tenant_id='10000000-0000-0000-0000-000000000001' and module_key='packages';
update public.tenant_entitlements set valid_until=now()-interval '1 second' where tenant_id='10000000-0000-0000-0000-000000000001' and module_key='packages';
set local role authenticated;
select throws_ok($$select public.module_probe('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','packages')$$,'42501',null,'RPC nega entitlement expirado');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='b@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select ok(public.check_access('20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000011','agenda.test','agenda'),'B autoriza Agenda');
select ok(not public.check_access('20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000011','packages.test','packages'),'B nega Pacotes');
select is((select count(*)::int from public.module_test_records),1,'RLS B não mostra Pacotes nem A');
select throws_ok($$select public.module_probe('20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000011','packages')$$,'42501',null,'RPC B nega Pacotes');
select throws_ok($$select public.preview_module('20000000-0000-0000-0000-000000000001','packages',true)$$,'42501',null,'B não testa módulo fora do contrato');
reset role;
-- Operador de plataforma sintético sem vínculo clínico implícito.
insert into private.platform_memberships(user_id,role) select id,'superadmin' from auth.users where email='revogado@example.com';
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='revogado@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select lives_ok($$select public.console_snapshot()$$,'Superadmin lê console');
select is((select count(*)::int from public.module_test_records),0,'Global não ganha acesso operacional');
select throws_ok($$select public.support_diagnostics('10000000-0000-0000-0000-000000000001')$$,'42501',null,'Mesmo superadmin exige grant de diagnóstico');
select lives_ok($$select public.grant_support('10000000-0000-0000-0000-000000000001',auth.uid(),'diagnostics',15,'Incidente sintético autorizado')$$,'Grant temporário registrado');
select ok(public.support_diagnostics('10000000-0000-0000-0000-000000000001') ? 'pending_deliveries','Diagnóstico com grant contém contagem');
select ok(not public.support_diagnostics('10000000-0000-0000-0000-000000000001') ? 'email','Diagnóstico não contém e-mail');
select throws_ok($$select public.grant_support('10000000-0000-0000-0000-000000000001',auth.uid(),'diagnostics',61,'Excesso de duração')$$,'22023',null,'Prazo de suporte limitado');
select lives_ok($$select public.revoke_support(id) from public.support_grants where grantee=auth.uid()$$,'Revoga suporte');
select throws_ok($$select public.support_diagnostics('10000000-0000-0000-0000-000000000001')$$,'42501',null,'Grant revogado nega diagnóstico');
select lives_ok($$select public.set_tenant_status('10000000-0000-0000-0000-000000000001',true,'Suspensão sintética contratual',now()+interval '1 day')$$,'Suspensão auditada');
reset role;
select ok(not private.job_allowed('10000000-0000-0000-0000-000000000001','agenda'),'Suspensão bloqueia jobs');
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='a@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select is((select count(*)::int from public.module_test_records),0,'Suspensão bloqueia RLS operacional');
select throws_ok($$select public.module_probe('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','agenda')$$,'42501',null,'Suspensão bloqueia RPC');
select throws_ok($$select public.export_tenant_metadata('10000000-0000-0000-0000-000000000001')$$,'42501',null,'Exportação sem grant negada');
reset role;
insert into public.support_grants(tenant_id,grantee,approver,reason,scope,expires_at) select '10000000-0000-0000-0000-000000000001',a.id,z.id,'Contrato sintético','export',now()+interval '15 minutes' from auth.users a cross join auth.users z where a.email='a@example.com' and z.email='revogado@example.com';
set local role authenticated;
select ok(public.export_tenant_metadata('10000000-0000-0000-0000-000000000001') ? 'units','Canal contratual permite exportar durante suspensão');
select is(jsonb_array_length(public.export_tenant_metadata('10000000-0000-0000-0000-000000000001')->'units'),1,'Exportação respeita escopo de unidades');
reset role;
update public.support_grants set expires_at=now()-interval '1 second' where scope='export';
set local role authenticated;
select throws_ok($$select public.export_tenant_metadata('10000000-0000-0000-0000-000000000001')$$,'42501',null,'Exportação expirada negada');
reset role;
select ok(exists(select 1 from public.audit_logs where action='suspend' and details->>'reason'='Suspensão sintética contratual'),'Trilha guarda motivo de suspensão');
select ok(exists(select 1 from public.audit_logs where entity='support_grants'),'Trilha guarda grant de suporte');
-- Continuação da cobertura de mudanças e revogação temporal.
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='revogado@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select lives_ok($$select public.set_tenant_status('10000000-0000-0000-0000-000000000001',false,'Retomada sintética')$$,'Reativação permitida e auditada');
select throws_ok($$select public.set_tenant_status('10000000-0000-0000-0000-000000000001',true,null)$$,'22023',null,'Motivo nulo não é auditável');
select lives_ok($$select public.update_onboarding('10000000-0000-0000-0000-000000000001','pilot','Marca piloto','Responsável','Evidência sintética do piloto')$$,'Onboarding registra etapa e evidência');
select lives_ok($$select public.update_subscription('10000000-0000-0000-0000-000000000001','grace',3,'Carência sintética contratada')$$,'Situação e quota contratada registradas');
select lives_ok($$select public.set_tenant_plan('10000000-0000-0000-0000-000000000001','essential','Downgrade sintético')$$,'Mudança de plano auditada');
select throws_ok($$select public.set_member_scope('10000000-0000-0000-0000-000000000001',(select id from public.tenant_memberships limit 1),array['20000000-0000-0000-0000-000000000011']::uuid[],'Escopo cruzado inválido')$$,'42501',null,'Não seleciona vínculo sem autoridade operacional implícita');
reset role;
update public.tenant_entitlements set valid_until=null where tenant_id='10000000-0000-0000-0000-000000000001' and module_key='packages';
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='a@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select ok(not public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','packages.test','packages'),'Downgrade retira Pacotes apesar de registro preservado');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='revogado@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select lives_ok($$select public.set_module_override('10000000-0000-0000-0000-000000000001','packages',true,now()+interval '1 day','Addon sintético contratado')$$,'Override com vigência concedido');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='a@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select ok(public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','packages.test','packages'),'Override vigente autoriza módulo adicional');
create temp table second_preview as select public.preview_module('10000000-0000-0000-0000-000000000001','packages',false) id;
select ok((public.test_module_change((select id from second_preview),'10000000-0000-0000-0000-000000000011')->>'can_publish')::boolean,'Teste temporário valida candidato');
select ok(public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','packages.test','packages'),'Teste temporário não muda autoridade operacional');
reset role;
update public.module_changes set expires_at=now()-interval '1 second' where id=(select id from second_preview);
set local role authenticated;
select throws_ok($$select public.publish_module((select id from second_preview))$$,'42501',null,'Prévia expirada não publica');
select throws_ok($$select public.test_module_change((select id from second_preview),'10000000-0000-0000-0000-000000000011')$$,'42501',null,'Prévia expirada não testa');
reset role;
update public.tenant_entitlements set configured=false where tenant_id='10000000-0000-0000-0000-000000000001' and module_key='agenda';
set local role authenticated;
select ok(not public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','packages.test','packages'),'Dependência desligada retira autorização do dependente');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='revogado@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select lives_ok($$select public.grant_support('10000000-0000-0000-0000-000000000001',auth.uid(),'diagnostics',1,'Incidente sintético temporário')$$,'Concessão curta criada');
reset role;
update public.support_grants set expires_at=now()-interval '1 second' where scope='diagnostics';
set local role authenticated;
select throws_ok($$select public.support_diagnostics('10000000-0000-0000-0000-000000000001')$$,'42501',null,'Concessão expirada não retorna diagnóstico');
reset role;
select ok(exists(select 1 from public.audit_logs where action='reactivate'),'Trilha de reativação');
select ok(exists(select 1 from public.audit_logs where action='plan' and details->>'plan'='essential'),'Trilha do plano e motivo');
select ok(exists(select 1 from public.audit_logs where action='onboarding' and details->>'state'='pilot'),'Trilha da etapa de onboarding');

select * from finish();
rollback;
